#include "unity.h"
#include "header.h"
#include "helpers.h"

typedef struct stdout_capture_t stdout_capture_t;

void setUp(void) { }
void tearDown(void) { }

void unit_test_printEPS_basic_valid_input(void) {
    // Setup: create a small set of observations and clusters
    // 2 clusters, 4 points, each cluster gets 2 points
    size_t len = 4;
    int k = 2;

    observation pts[4] = {
        {10.0, 10.0, 0},
        {12.0, 11.0, 0},
        {30.0, 32.0, 1},
        {29.0, 31.0, 1}
    };

    cluster cent[2] = {
        {11.0, 10.5, 2},
        {29.5, 31.5, 2}
    };

    // Capture stdout
    stdout_capture_t *cap = capture_stdout_start();

    // Test: call function under test
    printEPS(pts, len, cent, k);

    // Stop capture and get output
    char *output = capture_stdout_stop(cap);

    // Assertions: output should not be empty and should contain EPS header and cluster info
    TEST_ASSERT_NOT_NULL(output);
    // assert_stdout_not_empty(cap); // removed to avoid use-after-free

    // Check for EPS header
    TEST_ASSERT_NOT_NULL(strstr(output, "%!PS-Adobe-3.0 EPSF-3.0"));
    // Check for BoundingBox
    TEST_ASSERT_NOT_NULL(strstr(output, "%%%%BoundingBox: -5 -5 410 410"));
    // Check for centroid marker (should contain 's' operator)
    TEST_ASSERT_NOT_NULL(strstr(output, "s
"));

    // Check that at least one point for each cluster is drawn (should contain 'c
')
    TEST_ASSERT_NOT_NULL(strstr(output, "c
"));

    // Cleanup
    free(output);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_printEPS_basic_valid_input);
    return UNITY_END();
}


