// Asserts that each observation in the array has the expected group assignment. Prints a message if a mismatch is found.
void helper_assert_observation_group(observation *observations, size_t size, const int *expected_groups) {
    for (size_t i = 0; i < size; ++i) {
        if (observations[i].group != expected_groups[i]) {
            printf("Assertion failed: Observation %zu has group %d, expected %d
", i, observations[i].group, expected_groups[i]);
        }
    }
}

// Asserts that the centroids of clusters match the expected x and y values within a small epsilon. Prints a message if a mismatch is found.
void helper_assert_cluster_centroid(cluster *clusters, int k, const double *expected_x, const double *expected_y, double epsilon) {
    for (int i = 0; i < k; ++i) {
        if (fabs(clusters[i].x - expected_x[i]) > epsilon || fabs(clusters[i].y - expected_y[i]) > epsilon) {
            printf("Assertion failed: Cluster %d centroid (%.6f, %.6f), expected (%.6f, %.6f)
", i, clusters[i].x, clusters[i].y, expected_x[i], expected_y[i]);
        }
    }
}

// ========== Searched From Pool - Utility Operations ==========

// Function: capture_stdout_start (from helper pool)
stdout_capture_t *capture_stdout_start(void) {
    stdout_capture_t *cap = malloc(sizeof(stdout_capture_t));
    if (!cap) return NULL;
    cap->buffer = NULL;
    cap->buffer_size = 0;
    /* Create a pipe */
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        free(cap);
        return NULL;
    }
    cap->pipe_read_fd = pipefd[0];
    cap->pipe_write_fd = pipefd[1];
    /* Save original stdout */
    cap->saved_stdout_fd = dup(STDOUT_FILENO);
    if (cap->saved_stdout_fd == -1) {
        close(cap->pipe_read_fd);
        close(cap->pipe_write_fd);
        free(cap);
        return NULL;
    }
    /* Redirect stdout to the pipe write end */
    if (dup2(cap->pipe_write_fd, STDOUT_FILENO) == -1) {
        close(cap->saved_stdout_fd);
        close(cap->pipe_read_fd);
        close(cap->pipe_write_fd);
        free(cap);
        return NULL;
    }
    return cap;
}

// Function: capture_stdout_stop (from helper pool)
char *capture_stdout_stop(stdout_capture_t *cap) {
    if (!cap) return NULL;
    /* Flush stdout to ensure all output is written to pipe */
    fflush(stdout);
    /* Close write end of pipe to signal EOF */
    close(cap->pipe_write_fd);
    /* Restore original stdout */
    dup2(cap->saved_stdout_fd, STDOUT_FILENO);
    close(cap->saved_stdout_fd);
    /* Read captured output from pipe */
    size_t total_read = 0;
    size_t buffer_capacity = 1024;
    char *buffer = malloc(buffer_capacity);
    if (!buffer) {
        close(cap->pipe_read_fd);
        free(cap);
        return NULL;
    }
    ssize_t bytes_read;
    while ((bytes_read = read(cap->pipe_read_fd, buffer + total_read,
                               buffer_capacity - total_read - 1)) > 0) {
        total_read += bytes_read;
        if (total_read >= buffer_capacity - 1) {
            buffer_capacity *= 2;
            char *new_buffer = realloc(buffer, buffer_capacity);
            if (!new_buffer) {
                free(buffer);
                close(cap->pipe_read_fd);
                free(cap);
                return NULL;
            }
            buffer = new_buffer;
        }
    }
    buffer[total_read] = '\0';
    close(cap->pipe_read_fd);
    free(cap);
    return buffer;
}

// ========== Created - Utility Operations ==========

// Generates an array of observations placed evenly on a circle of given radius and center. The caller is responsible for freeing the returned array.
observation *helper_generate_observations_circle(size_t num_points, double radius, double center_x, double center_y) {
    observation *arr = (observation *)malloc(num_points * sizeof(observation));
    if (!arr) return NULL;
    for (size_t i = 0; i < num_points; ++i) {
        double angle = 2.0 * M_PI * i / num_points;
        arr[i].x = center_x + radius * cos(angle);
        arr[i].y = center_y + radius * sin(angle);
        arr[i].group = 0;
    }
    return arr;
}

// Frees the memory allocated for the clusters array.
void helper_free_clusters(cluster *clusters) {
    free(clusters);
}


